reply:
```turtle
@prefix ht:   <http://example.org/onto/hypertension#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .

<http://example.org/onto/hypertension> a owl:Ontology ;
    rdfs:label "Hypertension Ontology"@en ;
    skos:definition "An ontology modeling the classification, etiology, measurement, treatment and target-organ consequences of hypertension as described in the corpus."@en .

#################################################################
# TOP-LEVEL DISJOINTNESS
#################################################################

owl:AllDisjointClasses [
    owl:members ( ht:BloodPressureReading ht:Hypertension ht:Antihypertensive
                  ht:SecondaryCause ht:TargetOrganDamage ht:RiskFactor )
] .

#################################################################
# MEASUREMENT AXIS
#################################################################

ht:BloodPressureReading a owl:Class ;
    rdfs:label "Blood Pressure Reading"@en ;
    skos:definition "A measured pair of systolic and diastolic values expressed in millimetres of mercury."@en ;
    rdfs:subClassOf [ a owl:Restriction ; owl:onProperty ht:hasSystolicValue ;
          owl:qualifiedCardinality 1 ; owl:onDataRange xsd:integer ] ,
        [ a owl:Restriction ; owl:onProperty ht:hasDiastolicValue ;
          owl:qualifiedCardinality 1 ; owl:onDataRange xsd:integer ] .

ht:hasSystolicValue a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has systolic value"@en ;
    skos:definition "The maximum arterial pressure during one heartbeat, in mmHg."@en ;
    rdfs:domain ht:BloodPressureReading ; rdfs:range xsd:integer .

ht:hasDiastolicValue a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has diastolic value"@en ;
    skos:definition "The minimum arterial pressure between heartbeats, in mmHg."@en ;
    rdfs:domain ht:BloodPressureReading ; rdfs:range xsd:integer .

ht:BloodPressureCategory a owl:Class ;
    rdfs:label "Blood Pressure Category"@en ;
    skos:definition "An ACC/AHA 2017 band of blood pressure values (Normal, Elevated, Stage 1, Stage 2) used to classify a reading."@en ;
    rdfs:comment "Models ONE classification scheme (ACC/AHA 2017). Competing guideline schemes (ESC/ESH grades, JNC7 prehypertension/stage1/stage2, WHO, NICE) use different cut-points and are noted in comments rather than modeled as parallel class trees."@en .

ht:hasBloodPressureCategory a owl:ObjectProperty ;
    rdfs:label "has blood pressure category"@en ;
    skos:definition "Relates a blood pressure reading to the category it falls into."@en ;
    rdfs:domain ht:BloodPressureReading ; rdfs:range ht:BloodPressureCategory ;
    owl:inverseOf ht:isBloodPressureCategoryOf .
ht:isBloodPressureCategoryOf a owl:ObjectProperty ;
    rdfs:label "is blood pressure category of"@en ;
    skos:definition "Inverse of has blood pressure category."@en ;
    rdfs:domain ht:BloodPressureCategory ; rdfs:range ht:BloodPressureReading .

ht:NormalBloodPressure a owl:Class ;
    rdfs:label "Normal Blood Pressure"@en ;
    skos:definition "A reading with systolic pressure less than 120 mmHg and diastolic pressure less than 80 mmHg."@en ;
    rdfs:subClassOf ht:BloodPressureCategory ;
    owl:equivalentClass [ owl:intersectionOf ( ht:BloodPressureReading
        [ a owl:Restriction ; owl:onProperty ht:hasSystolicValue ; owl:someValuesFrom
            [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
              owl:withRestrictions ( [ xsd:maxExclusive 120 ] ) ] ]
        [ a owl:Restriction ; owl:onProperty ht:hasDiastolicValue ; owl:someValuesFrom
            [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
              owl:withRestrictions ( [ xsd:maxExclusive 80 ] ) ] ] ) ] .

ht:ElevatedBloodPressure a owl:Class ;
    rdfs:label "Elevated Blood Pressure"@en ;
    skos:definition "A reading with systolic pressure of 120 to 129 mmHg and diastolic pressure less than 80 mmHg; formerly called prehypertension."@en ;
    rdfs:subClassOf ht:BloodPressureCategory ;
    owl:equivalentClass [ owl:intersectionOf ( ht:BloodPressureReading
        [ a owl:Restriction ; owl:onProperty ht:hasSystolicValue ; owl:someValuesFrom
            [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
              owl:withRestrictions ( [ xsd:minInclusive 120 ] [ xsd:maxInclusive 129 ] ) ] ]
        [ a owl:Restriction ; owl:onProperty ht:hasDiastolicValue ; owl:someValuesFrom
            [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
              owl:withRestrictions ( [ xsd:maxExclusive 80 ] ) ] ] ) ] .

ht:Stage1Hypertension a owl:Class ;
    rdfs:label "Stage 1 Hypertension"@en ;
    skos:definition "A reading with systolic pressure of 130 to 139 mmHg or diastolic pressure of 80 to 89 mmHg."@en ;
    rdfs:subClassOf ht:BloodPressureCategory ;
    owl:equivalentClass [ owl:intersectionOf ( ht:BloodPressureReading
        [ owl:unionOf (
            [ a owl:Restriction ; owl:onProperty ht:hasSystolicValue ; owl:someValuesFrom
                [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
                  owl:withRestrictions ( [ xsd:minInclusive 130 ] [ xsd:maxInclusive 139 ] ) ] ]
            [ a owl:Restriction ; owl:onProperty ht:hasDiastolicValue ; owl:someValuesFrom
                [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
                  owl:withRestrictions ( [ xsd:minInclusive 80 ] [ xsd:maxInclusive 89 ] ) ] ]
        ) ] ) ] .

ht:Stage2Hypertension a owl:Class ;
    rdfs:label "Stage 2 Hypertension"@en ;
    skos:definition "A reading with systolic pressure of 140 mmHg or greater or diastolic pressure of 90 mmHg or greater."@en ;
    rdfs:subClassOf ht:BloodPressureCategory ;
    owl:equivalentClass [ owl:intersectionOf ( ht:BloodPressureReading
        [ owl:unionOf (
            [ a owl:Restriction ; owl:onProperty ht:hasSystolicValue ; owl:someValuesFrom
                [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
                  owl:withRestrictions ( [ xsd:minInclusive 140 ] ) ] ]
            [ a owl:Restriction ; owl:onProperty ht:hasDiastolicValue ; owl:someValuesFrom
                [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
                  owl:withRestrictions ( [ xsd:minInclusive 90 ] ) ] ]
        ) ] ) ] .

owl:AllDisjointClasses [
    owl:members ( ht:NormalBloodPressure ht:ElevatedBloodPressure
                  ht:Stage1Hypertension ht:Stage2Hypertension )
] .

ht:HypertensiveBloodPressureReading a owl:Class ;
    rdfs:label "Hypertensive Blood Pressure Reading"@en ;
    skos:definition "A reading that falls into Stage 1 or Stage 2 hypertension, i.e. a reading that is itself hypertensive in level."@en ;
    owl:equivalentClass [ owl:unionOf ( ht:Stage1Hypertension ht:Stage2Hypertension ) ] .

#################################################################
# HYPERTENSION (DISEASE) TOP CLASS AND DIAGNOSTIC THRESHOLD
#################################################################

ht:Hypertension a owl:Class ;
    rdfs:label "Hypertension"@en ;
    skos:altLabel "High Blood Pressure"@en ;
    skos:definition "A chronic medical condition characterized by sustained elevation of arterial blood pressure."@en ;
    rdfs:comment "The diagnostic systolic threshold is contested across guidelines: the 2017 ACC/AHA guideline sets it at 130 mmHg, while ESC/ESH, JNC7/JNC8, WHO and ISH guidelines retain 140 mmHg. Both values are recorded via hasDiagnosticSystolicThreshold rather than via separate per-guideline subclasses."@en .

ht:hasDiagnosticSystolicThreshold a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has diagnostic systolic threshold"@en ;
    skos:definition "The systolic blood pressure value, in mmHg, at or above which a guideline diagnoses hypertension."@en ;
    rdfs:domain ht:Hypertension ; rdfs:range xsd:integer ;
    rdfs:comment "Competing values documented in the corpus: 130 (ACC/AHA 2017) versus 140 (ESC/ESH, JNC7, WHO, ISH)."@en .

ht:hasBloodPressureReading a owl:ObjectProperty ;
    rdfs:label "has blood pressure reading"@en ;
    skos:definition "Relates a hypertensive condition to a blood pressure reading associated with it."@en ;
    rdfs:domain ht:Hypertension ; rdfs:range ht:BloodPressureReading ;
    owl:inverseOf ht:isBloodPressureReadingOf .
ht:isBloodPressureReadingOf a owl:ObjectProperty ;
    rdfs:label "is blood pressure reading of"@en ;
    skos:definition "Inverse of has blood pressure reading."@en ;
    rdfs:domain ht:BloodPressureReading ; rdfs:range ht:Hypertension .

ht:hasOfficeBloodPressureReading a owl:ObjectProperty ;
    rdfs:subPropertyOf ht:hasBloodPressureReading ;
    rdfs:label "has office blood pressure reading"@en ;
    skos:definition "Relates a hypertensive condition to a blood pressure reading taken in a clinic/office setting."@en ;
    rdfs:domain ht:Hypertension ; rdfs:range ht:BloodPressureReading .

ht:hasOutOfOfficeBloodPressureReading a owl:ObjectProperty ;
    rdfs:subPropertyOf ht:hasBloodPressureReading ;
    rdfs:label "has out of office blood pressure reading"@en ;
    skos:definition "Relates a hypertensive condition to a blood pressure reading taken outside the clinic, e.g. by ambulatory or home monitoring."@en ;
    rdfs:domain ht:Hypertension ; rdfs:range ht:BloodPressureReading .

#################################################################
# PRIMARY VS SECONDARY HYPERTENSION
#################################################################

ht:PrimaryHypertension a owl:Class ;
    rdfs:label "Primary Hypertension"@en ;
    skos:altLabel "Essential Hypertension"@en , "Idiopathic Hypertension"@en ;
    skos:definition "Hypertension with no single identifiable underlying cause, arising from the interaction of genetic predisposition and environmental/lifestyle factors; accounts for approximately 85-95% of cases."@en ;
    rdfs:subClassOf ht:Hypertension .

ht:SecondaryHypertension a owl:Class ;
    rdfs:label "Secondary Hypertension"@en ;
    skos:altLabel "Inessential Hypertension"@en ;
    skos:definition "Hypertension that is secondary to a specific, identifiable, and often treatable underlying cause; accounts for approximately 5-15% of cases, with higher prevalence in children and younger adults."@en ;
    rdfs:subClassOf ht:Hypertension .

owl:AllDisjointClasses [ owl:members ( ht:PrimaryHypertension ht:SecondaryHypertension ) ] .

ht:hasSecondaryCause a owl:ObjectProperty ;
    rdfs:label "has secondary cause"@en ;
    skos:definition "Relates secondary hypertension to its identifiable underlying cause."@en ;
    rdfs:domain ht:SecondaryHypertension ; rdfs:range ht:SecondaryCause ;
    owl:inverseOf ht:isSecondaryCauseOf .
ht:isSecondaryCauseOf a owl:ObjectProperty ;
    rdfs:label "is secondary cause of"@en ;
    skos:definition "Inverse of has secondary cause."@en ;
    rdfs:domain ht:SecondaryCause ; rdfs:range ht:SecondaryHypertension .

#################################################################
# SECONDARY CAUSE TAXONOMY
#################################################################

ht:SecondaryCause a owl:Class ;
    rdfs:label "Secondary Cause"@en ;
    skos:definition "An identifiable underlying condition, substance, or medication that produces secondary hypertension."@en .

ht:RenalCause a owl:Class ; rdfs:subClassOf ht:SecondaryCause ;
    rdfs:label "Renal Cause"@en ;
    skos:definition "A secondary cause of hypertension arising from kidney disease; the most common category of secondary hypertension."@en .

ht:RenalParenchymalDisease a owl:Class ; rdfs:subClassOf ht:RenalCause ;
    rdfs:label "Renal Parenchymal Disease"@en ;
    skos:definition "Kidney disease affecting the renal parenchyma, including diabetic nephropathy, glomerulonephritis, interstitial disorders, polycystic kidney disease, and lupus nephritis, that causes secondary hypertension."@en .

ht:RenovascularDisease a owl:Class ; rdfs:subClassOf ht:RenalCause ;
    rdfs:label "Renovascular Disease"@en ;
    skos:definition "A disorder of the renal arterial supply, producing hypertension through narrowing of the renal artery."@en .

ht:RenalArteryStenosis a owl:Class ; rdfs:subClassOf ht:RenovascularDisease ;
    rdfs:label "Renal Artery Stenosis"@en ;
    skos:definition "Narrowing of the renal artery, the characteristic lesion of renovascular disease causing secondary hypertension."@en .

owl:AllDisjointClasses [ owl:members ( ht:RenalParenchymalDisease ht:RenovascularDisease ) ] .

ht:EndocrineCause a owl:Class ; rdfs:subClassOf ht:SecondaryCause ;
    rdfs:label "Endocrine Cause"@en ;
    skos:definition "A hormonal/endocrine disorder causing secondary hypertension."@en .

ht:PrimaryAldosteronism a owl:Class ; rdfs:subClassOf ht:EndocrineCause ;
    rdfs:label "Primary Aldosteronism"@en ;
    skos:altLabel "Conn Syndrome"@en ;
    skos:definition "Autonomous overproduction of aldosterone by the adrenal gland, due to an aldosterone-producing adenoma or bilateral adrenal hyperplasia, causing sodium retention and hypertension; the most common endocrine cause of secondary hypertension and present in up to one in five patients with resistant hypertension."@en .

ht:Pheochromocytoma a owl:Class ; rdfs:subClassOf ht:EndocrineCause ;
    rdfs:label "Pheochromocytoma"@en ;
    skos:definition "A tumor causing excessive secretion of norepinephrine and epinephrine, promoting vasoconstriction and secondary hypertension."@en .

ht:CushingSyndrome a owl:Class ; rdfs:subClassOf ht:EndocrineCause ;
    rdfs:label "Cushing Syndrome"@en ;
    skos:definition "An endocrine disorder of excess glucocorticoids causing secondary hypertension."@en .

ht:ThyroidDisease a owl:Class ; rdfs:subClassOf ht:EndocrineCause ;
    rdfs:label "Thyroid Disease"@en ;
    skos:definition "Hyperthyroidism or hypothyroidism recognized as a cause of secondary hypertension."@en .

ht:PrimaryHyperparathyroidism a owl:Class ; rdfs:subClassOf ht:EndocrineCause ;
    rdfs:label "Primary Hyperparathyroidism"@en ;
    skos:definition "A parathyroid disorder recognized as a contributor to secondary hypertension."@en .

owl:AllDisjointClasses [ owl:members ( ht:PrimaryAldosteronism ht:Pheochromocytoma
                                       ht:CushingSyndrome ht:ThyroidDisease ht:PrimaryHyperparathyroidism ) ] .

ht:VascularCause a owl:Class ; rdfs:subClassOf ht:SecondaryCause ;
    rdfs:label "Vascular Cause"@en ;
    skos:definition "A structural vascular abnormality causing secondary hypertension, typically affecting younger patients."@en .

ht:AorticCoarctation a owl:Class ; rdfs:subClassOf ht:VascularCause ;
    rdfs:label "Aortic Coarctation"@en ;
    skos:definition "A congenital narrowing of the aorta that is a recognized vascular cause of secondary hypertension."@en .

ht:ObstructiveSleepApnea a owl:Class ; rdfs:subClassOf ht:SecondaryCause ;
    rdfs:label "Obstructive Sleep Apnea"@en ;
    skos:altLabel "OSA"@en ;
    skos:definition "A sleep-related breathing disorder that is one of the most common causes of secondary hypertension and of secondary hypertension underlying resistant hypertension."@en .

ht:DrugInducedCause a owl:Class ; rdfs:subClassOf ht:SecondaryCause ;
    rdfs:label "Drug Induced Cause"@en ;
    skos:definition "Secondary hypertension caused by a medication or substance, including NSAIDs, sympathomimetic decongestants, stimulant medications, certain antidepressants, systemic corticosteroids, mineralocorticoid-like substances such as licorice, oral contraceptives, immunosuppressants such as cyclosporine, and recreational substances such as cocaine and methamphetamine; discontinuing the offending agent may resolve the hypertension."@en .

owl:AllDisjointClasses [
    owl:members ( ht:RenalCause ht:EndocrineCause ht:VascularCause
                  ht:ObstructiveSleepApnea ht:DrugInducedCause )
] .

#################################################################
# HYPERTENSIVE CRISIS
#################################################################

ht:HypertensiveCrisis a owl:Class ;
    rdfs:subClassOf ht:Hypertension ;
    rdfs:label "Hypertensive Crisis"@en ;
    skos:definition "A severe, acute elevation of blood pressure, conventionally a systolic pressure of 180 mmHg or more or a diastolic pressure of 120 mmHg or more; classified into urgency or emergency according to the presence of acute target-organ damage."@en ;
    owl:equivalentClass [ owl:intersectionOf (
        ht:Hypertension
        [ a owl:Restriction ; owl:onProperty ht:hasBloodPressureReading ; owl:someValuesFrom
            [ owl:intersectionOf ( ht:BloodPressureReading
                [ owl:unionOf (
                    [ a owl:Restriction ; owl:onProperty ht:hasSystolicValue ; owl:someValuesFrom
                        [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
                          owl:withRestrictions ( [ xsd:minInclusive 180 ] ) ] ]
                    [ a owl:Restriction ; owl:onProperty ht:hasDiastolicValue ; owl:someValuesFrom
                        [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
                          owl:withRestrictions ( [ xsd:minInclusive 120 ] ) ] ]
                ) ] ) ]
        ]
    ) ] .

ht:HypertensiveEmergency a owl:Class ;
    rdfs:subClassOf ht:HypertensiveCrisis ;
    rdfs:label "Hypertensive Emergency"@en ;
    skos:definition "A hypertensive crisis accompanied by acute hypertension-mediated target-organ damage, requiring prompt controlled reduction of blood pressure usually with intravenous agents."@en ;
    owl:equivalentClass [ owl:intersectionOf (
        ht:HypertensiveCrisis
        [ a owl:Restriction ; owl:onProperty ht:hasTargetOrganDamage ; owl:someValuesFrom ht:TargetOrganDamage ]
    ) ] .

ht:HypertensiveUrgency a owl:Class ;
    rdfs:subClassOf ht:HypertensiveCrisis ;
    rdfs:label "Hypertensive Urgency"@en ;
    skos:definition "A hypertensive crisis without evidence of acute target-organ damage, managed with gradual oral reduction of blood pressure over 24 to 48 hours."@en ;
    owl:equivalentClass [ owl:intersectionOf (
        ht:HypertensiveCrisis
        [ a owl:Restriction ; owl:onProperty ht:hasTargetOrganDamage ;
          owl:onClass ht:TargetOrganDamage ; owl:maxQualifiedCardinality "0"^^xsd:nonNegativeInteger ]
    ) ] .

owl:AllDisjointClasses [ owl:members ( ht:HypertensiveUrgency ht:HypertensiveEmergency ) ] .

ht:hasTargetOrganDamage a owl:ObjectProperty ;
    rdfs:label "has target organ damage"@en ;
    skos:definition "Relates a hypertensive condition to a form of organ damage it has produced."@en ;
    rdfs:domain ht:Hypertension ; rdfs:range ht:TargetOrganDamage ;
    owl:inverseOf ht:isTargetOrganDamageOf .
ht:isTargetOrganDamageOf a owl:ObjectProperty ;
    rdfs:label "is target organ damage of"@en ;
    skos:definition "Inverse of has target organ damage."@en ;
    rdfs:domain ht:TargetOrganDamage ; rdfs:range ht:Hypertension .

#################################################################
# PHENOTYPES: WHITE COAT / MASKED / ISOLATED SYSTOLIC / RESISTANT
#################################################################

ht:WhiteCoatHypertension a owl:Class ;
    rdfs:subClassOf ht:Hypertension ;
    rdfs:label "White Coat Hypertension"@en ;
    skos:altLabel "White Coat Syndrome"@en ;
    skos:definition "A phenotype of consistently elevated office blood pressure with normal out-of-office blood pressure, believed to reflect anxiety in the clinical setting."@en ;
    owl:equivalentClass [ owl:intersectionOf (
        ht:Hypertension
        [ a owl:Restriction ; owl:onProperty ht:hasOfficeBloodPressureReading ; owl:someValuesFrom ht:HypertensiveBloodPressureReading ]
        [ a owl:Restriction ; owl:onProperty ht:hasOutOfOfficeBloodPressureReading ; owl:someValuesFrom ht:NormalBloodPressure ]
    ) ] .

ht:MaskedHypertension a owl:Class ;
    rdfs:subClassOf ht:Hypertension ;
    rdfs:label "Masked Hypertension"@en ;
    skos:definition "A phenotype of consistently normal office blood pressure with elevated out-of-office blood pressure, carrying cardiovascular risk similar to sustained hypertension."@en ;
    owl:equivalentClass [ owl:intersectionOf (
        ht:Hypertension
        [ a owl:Restriction ; owl:onProperty ht:hasOfficeBloodPressureReading ; owl:someValuesFrom ht:NormalBloodPressure ]
        [ a owl:Restriction ; owl:onProperty ht:hasOutOfOfficeBloodPressureReading ; owl:someValuesFrom ht:HypertensiveBloodPressureReading ]
    ) ] .

owl:AllDisjointClasses [ owl:members ( ht:WhiteCoatHypertension ht:MaskedHypertension ) ] .

ht:IsolatedSystolicHypertension a owl:Class ;
    rdfs:subClassOf ht:Hypertension ;
    rdfs:label "Isolated Systolic Hypertension"@en ;
    skos:definition "The predominant form of hypertension in older adults, traditionally defined as a systolic pressure above 140 mmHg with a diastolic pressure below 90 mmHg, reflecting arterial stiffening; most cases are due to primary hypertension but some result from a secondary cause such as hypothyroidism, hyperthyroidism, chronic kidney disease, or atherosclerotic renal artery stenosis."@en ;
    rdfs:comment "The 2017 ACC/AHA guideline lowers the qualifying systolic threshold to 130 mmHg at all ages, conflicting with the traditional 140 mmHg criterion modeled here via hasDiagnosticSystolicThreshold on Hypertension."@en ;
    owl:equivalentClass [ owl:intersectionOf (
        ht:Hypertension
        [ a owl:Restriction ; owl:onProperty ht:hasBloodPressureReading ; owl:someValuesFrom
            [ owl:intersectionOf ( ht:BloodPressureReading
                [ a owl:Restriction ; owl:onProperty ht:hasSystolicValue ; owl:someValuesFrom
                    [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
                      owl:withRestrictions ( [ xsd:minInclusive 140 ] ) ] ]
                [ a owl:Restriction ; owl:onProperty ht:hasDiastolicValue ; owl:someValuesFrom
                    [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
                      owl:withRestrictions ( [ xsd:maxExclusive 90 ] ) ] ] ) ]
        ]
    ) ] .

ht:ResistantHypertension a owl:Class ;
    rdfs:subClassOf ht:Hypertension ;
    rdfs:label "Resistant Hypertension"@en ;
    skos:definition "Blood pressure that remains uncontrolled despite adherence to three or more suitably dosed antihypertensive medications of different classes, one of which is a diuretic, after the white-coat effect and non-adherence have been excluded."@en ;
    rdfs:comment "True resistant hypertension additionally requires that the three-or-more agents belong to different pharmacological classes and that the white-coat effect be excluded by ambulatory or home monitoring; these qualitative conditions are noted here rather than fully formalized."@en ;
    owl:equivalentClass [ owl:intersectionOf (
        ht:Hypertension
        [ a owl:Restriction ; owl:onProperty ht:hasAntihypertensive ;
          owl:onClass ht:Antihypertensive ; owl:minQualifiedCardinality "3"^^xsd:nonNegativeInteger ]
    ) ] .

#################################################################
# TARGET ORGAN DAMAGE
#################################################################

ht:TargetOrganDamage a owl:Class ;
    rdfs:label "Target Organ Damage"@en ;
    skos:definition "Structural or functional damage to an organ system caused by sustained or acute elevation of blood pressure."@en .

ht:HypertensiveHeartDisease a owl:Class ; rdfs:subClassOf ht:TargetOrganDamage ;
    rdfs:label "Hypertensive Heart Disease"@en ;
    skos:definition "Structural and functional changes in the left ventricle, left atrium, and coronary arteries resulting from chronic blood pressure elevation, including hypertrophy, remodeling, coronary microvascular dysfunction, and progression to heart failure."@en .

ht:LeftVentricularHypertrophy a owl:Class ; rdfs:subClassOf ht:HypertensiveHeartDisease ;
    rdfs:label "Left Ventricular Hypertrophy"@en ;
    skos:altLabel "LVH"@en ;
    skos:definition "Thickening of the left ventricular wall in compensatory response to chronic pressure overload; the hallmark structural manifestation of hypertensive heart disease."@en .

ht:HypertensiveRetinopathy a owl:Class ; rdfs:subClassOf ht:TargetOrganDamage ;
    rdfs:label "Hypertensive Retinopathy"@en ;
    skos:definition "Damage to the retina and retinal circulation due to sustained or abrupt elevation of blood pressure, visible on ophthalmoscopy and correlating with the severity and chronicity of hypertension."@en ;
    rdfs:comment "The corpus also describes the Keith-Wagener-Barker four-grade severity system; per scope clamp, grades are not modeled as separate classes, only the underlying retinal findings."@en .

ht:HypertensiveNephropathy a owl:Class ; rdfs:subClassOf ht:TargetOrganDamage ;
    rdfs:label "Hypertensive Nephropathy"@en ;
    skos:altLabel "Hypertensive Kidney Disease"@en ;
    skos:definition "Kidney damage attributable to chronic hypertension, characterized by nephrosclerosis (hardening and thickening of small renal vessels, glomeruli, tubules, and interstitium) reducing blood and oxygen supply and progressively lowering filtering capacity, potentially culminating in end-stage kidney disease."@en .

ht:HypertensiveEncephalopathy a owl:Class ; rdfs:subClassOf ht:TargetOrganDamage ;
    rdfs:label "Hypertensive Encephalopathy"@en ;
    skos:definition "Acute brain swelling and dysfunction caused by severely elevated blood pressure, presenting with headache, confusion, or visual disturbance."@en .

owl:AllDisjointClasses [
    owl:members ( ht:HypertensiveHeartDisease ht:HypertensiveRetinopathy
                  ht:HypertensiveNephropathy ht:HypertensiveEncephalopathy )
] .

ht:RetinalFinding a owl:Class ;
    rdfs:label "Retinal Finding"@en ;
    skos:definition "A specific ophthalmoscopic finding of hypertensive retinopathy, reflecting damage to the retinal vessels."@en .

ht:ArteriolarNarrowing a owl:Class ; rdfs:subClassOf ht:RetinalFinding ;
    rdfs:label "Arteriolar Narrowing"@en ;
    skos:definition "Generalized or focal narrowing of the retinal arterioles, an early sign of hypertensive retinopathy."@en .

ht:ArteriovenousNicking a owl:Class ; rdfs:subClassOf ht:RetinalFinding ;
    rdfs:label "Arteriovenous Nicking"@en ;
    skos:altLabel "AV Nicking"@en , "AV Nipping"@en ;
    skos:definition "Compression of a retinal vein where it is crossed by a sclerotic arteriole, a sign of hypertensive retinopathy."@en .

ht:RetinalHemorrhage a owl:Class ; rdfs:subClassOf ht:RetinalFinding ;
    rdfs:label "Retinal Hemorrhage"@en ;
    skos:definition "Bleeding into the retinal tissue, including flame-shaped and blot hemorrhages, seen in more advanced hypertensive retinopathy."@en .

ht:CottonWoolSpot a owl:Class ; rdfs:subClassOf ht:RetinalFinding ;
    rdfs:label "Cotton Wool Spot"@en ;
    skos:definition "An ischemic retinal lesion appearing as a white, fluffy patch, seen in advanced hypertensive retinopathy."@en .

ht:HardExudate a owl:Class ; rdfs:subClassOf ht:RetinalFinding ;
    rdfs:label "Hard Exudate"@en ;
    skos:definition "Lipid deposits leaking into the retinal tissue as the blood-retinal barrier breaks down in advanced hypertensive retinopathy."@en .

ht:Papilledema a owl:Class ; rdfs:subClassOf ht:RetinalFinding ;
    rdfs:label "Papilledema"@en ;
    skos:altLabel "Optic Disc Edema"@en ;
    skos:definition "Swelling of the optic disc, the most severe retinal finding, indicating malignant hypertensive retinopathy."@en .

owl:AllDisjointClasses [
    owl:members ( ht:ArteriolarNarrowing ht:ArteriovenousNicking ht:RetinalHemorrhage
                  ht:CottonWoolSpot ht:HardExudate ht:Papilledema )
] .

ht:hasRetinalFinding a owl:ObjectProperty ;
    rdfs:label "has retinal finding"@en ;
    skos:definition "Relates hypertensive retinopathy to a specific retinal finding observed on examination."@en ;
    rdfs:domain ht:HypertensiveRetinopathy ; rdfs:range ht:RetinalFinding ;
    owl:inverseOf ht:isRetinalFindingOf .
ht:isRetinalFindingOf a owl:ObjectProperty ;
    rdfs:label "is retinal finding of"@en ;
    skos:definition "Inverse of has retinal finding."@en ;
    rdfs:domain ht:RetinalFinding ; rdfs:range ht:HypertensiveRetinopathy .

#################################################################
# RISK FACTORS
#################################################################

ht:RiskFactor a owl:Class ;
    rdfs:label "Risk Factor"@en ;
    skos:definition "A factor that increases the likelihood of developing hypertension."@en .

ht:ModifiableRiskFactor a owl:Class ; rdfs:subClassOf ht:RiskFactor ;
    rdfs:label "Modifiable Risk Factor"@en ;
    skos:definition "A risk factor for hypertension that can be changed through behavior or treatment."@en .

ht:ExcessSaltIntake a owl:Class ; rdfs:subClassOf ht:ModifiableRiskFactor ;
    rdfs:label "Excess Salt Intake"@en ;
    skos:definition "Elevated dietary sodium intake, which increases the risk of developing hypertension, particularly in salt-sensitive individuals."@en .

ht:Obesity a owl:Class ; rdfs:subClassOf ht:ModifiableRiskFactor ;
    rdfs:label "Obesity"@en ;
    skos:definition "Excess body weight, a modifiable risk factor for hypertension; weight reduction can lower systolic blood pressure by 5 to 20 mmHg."@en .

ht:PhysicalInactivity a owl:Class ; rdfs:subClassOf ht:ModifiableRiskFactor ;
    rdfs:label "Physical Inactivity"@en ;
    skos:definition "Lack of regular exercise, a modifiable risk factor for hypertension."@en .

ht:TobaccoUse a owl:Class ; rdfs:subClassOf ht:ModifiableRiskFactor ;
    rdfs:label "Tobacco Use"@en ;
    skos:definition "Smoking or other tobacco use, a modifiable risk factor for hypertension and cardiovascular disease."@en .

ht:AlcoholUse a owl:Class ; rdfs:subClassOf ht:ModifiableRiskFactor ;
    rdfs:label "Alcohol Use"@en ;
    skos:definition "Consumption of alcohol, associated with higher blood pressure and a modifiable risk factor for hypertension."@en .

owl:AllDisjointClasses [
    owl:members ( ht:ExcessSaltIntake ht:Obesity ht:PhysicalInactivity ht:TobaccoUse ht:AlcoholUse )
] .

ht:NonModifiableRiskFactor a owl:Class ; rdfs:subClassOf ht:RiskFactor ;
    rdfs:label "Non Modifiable Risk Factor"@en ;
    skos:definition "A risk factor for hypertension that cannot be changed, such as age, sex, race, or family history."@en .

ht:AdvancingAge a owl:Class ; rdfs:subClassOf ht:NonModifiableRiskFactor ;
    rdfs:label "Advancing Age"@en ;
    skos:definition "Increasing age, a non-modifiable risk factor; prevalence of hypertension rises to approximately 60% of individuals above age 60."@en .

ht:FamilyHistory a owl:Class ; rdfs:subClassOf ht:NonModifiableRiskFactor ;
    rdfs:label "Family History"@en ;
    skos:definition "A family history of hypertension, a non-modifiable risk factor reflecting genetic predisposition."@en .

ht:Race a owl:Class ; rdfs:subClassOf ht:NonModifiableRiskFactor ;
    rdfs:label "Race"@en ;
    skos:definition "Race, a non-modifiable risk factor that also influences first-line treatment selection, notably between Black and non-Black populations."@en .

ht:GeneticPredisposition a owl:Class ; rdfs:subClassOf ht:NonModifiableRiskFactor ;
    rdfs:label "Genetic Predisposition"@en ;
    skos:definition "Inherited genetic variants influencing salt sensitivity and blood pressure regulation; more than 2,000 common genetic variants with small individual effects have been identified."@en .

owl:AllDisjointClasses [
    owl:members ( ht:AdvancingAge ht:FamilyHistory ht:Race ht:GeneticPredisposition )
] .

ht:hasRiskFactor a owl:ObjectProperty ;
    rdfs:label "has risk factor"@en ;
    skos:definition "Relates hypertension to a factor that increases the likelihood of its development."@en ;
    rdfs:domain ht:Hypertension ; rdfs:range ht:RiskFactor ;
    owl:inverseOf ht:isRiskFactorOf .
ht:isRiskFactorOf a owl:ObjectProperty ;
    rdfs:label "is risk factor of"@en ;
    skos:definition "Inverse of has risk factor."@en ;
    rdfs:domain ht:RiskFactor ; rdfs:range ht:Hypertension .

#################################################################
# TREATMENT: ANTIHYPERTENSIVE DRUG CLASSES
#################################################################

ht:Antihypertensive a owl:Class ;
    rdfs:label "Antihypertensive"@en ;
    skos:definition "A class of medication used to lower blood pressure."@en .

ht:ThiazideDiuretic a owl:Class ; rdfs:subClassOf ht:Antihypertensive ;
    rdfs:label "Thiazide Diuretic"@en ;
    skos:definition "A first-line antihypertensive class that blocks sodium reabsorption in the distal convoluted tubule of the nephron, promoting natriuresis and diuresis and reducing intravascular volume; includes thiazide-like agents such as chlorthalidone and indapamide."@en .

ht:AngiotensinConvertingEnzymeInhibitor a owl:Class ; rdfs:subClassOf ht:Antihypertensive ;
    rdfs:label "Angiotensin Converting Enzyme Inhibitor"@en ;
    skos:altLabel "ACE Inhibitor"@en , "ACEI"@en ;
    skos:definition "A first-line antihypertensive class that inhibits angiotensin-converting enzyme, reducing angiotensin II production and increasing bradykinin levels, producing vasodilation; preferred in patients with diabetes or chronic kidney disease, contraindicated in pregnancy, and associated with dry cough and rare angioedema."@en .

ht:AngiotensinReceptorBlocker a owl:Class ; rdfs:subClassOf ht:Antihypertensive ;
    rdfs:label "Angiotensin Receptor Blocker"@en ;
    skos:altLabel "ARB"@en ;
    skos:definition "A first-line antihypertensive class that blocks the binding of angiotensin II to the angiotensin type 1 receptor, with efficacy similar to ACE inhibitors but fewer adverse effects such as cough and a lower risk of angioedema; generally not combined with ACE inhibitors."@en .

ht:CalciumChannelBlocker a owl:Class ; rdfs:subClassOf ht:Antihypertensive ;
    rdfs:label "Calcium Channel Blocker"@en ;
    skos:altLabel "CCB"@en ;
    skos:definition "A first-line antihypertensive class that inhibits calcium entry through L-type voltage-gated calcium channels in cardiac and vascular smooth muscle."@en .

ht:Dihydropyridine a owl:Class ; rdfs:subClassOf ht:CalciumChannelBlocker ;
    rdfs:label "Dihydropyridine"@en ;
    skos:definition "A subtype of calcium channel blocker, such as amlodipine or nifedipine, that acts predominantly on vascular smooth muscle to cause peripheral vasodilation and is preferred for treating hypertension."@en .

ht:NonDihydropyridine a owl:Class ; rdfs:subClassOf ht:CalciumChannelBlocker ;
    rdfs:label "Non Dihydropyridine"@en ;
    skos:definition "A subtype of calcium channel blocker, such as verapamil or diltiazem, that primarily affects cardiac contractility and atrioventricular conduction and is better suited to arrhythmia management."@en .

owl:AllDisjointClasses [ owl:members ( ht:Dihydropyridine ht:NonDihydropyridine ) ] .

ht:BetaBlocker a owl:Class ; rdfs:subClassOf ht:Antihypertensive ;
    rdfs:label "Beta Blocker"@en ;
    skos:definition "An antihypertensive class that inhibits catecholamines from binding to beta-adrenergic receptors, reducing heart rate, cardiac contractility, and renin release; no longer recommended as first-line therapy for uncomplicated hypertension except when a compelling cardiac indication is present."@en .

owl:AllDisjointClasses [
    owl:members ( ht:ThiazideDiuretic ht:AngiotensinConvertingEnzymeInhibitor
                  ht:AngiotensinReceptorBlocker ht:CalciumChannelBlocker ht:BetaBlocker )
] .

ht:hasAntihypertensive a owl:ObjectProperty ;
    rdfs:label "has antihypertensive"@en ;
    skos:definition "Relates hypertension to an antihypertensive drug class used in its treatment."@en ;
    rdfs:domain ht:Hypertension ; rdfs:range ht:Antihypertensive ;
    owl:inverseOf ht:isAntihypertensiveOf .
ht:isAntihypertensiveOf a owl:ObjectProperty ;
    rdfs:label "is antihypertensive of"@en ;
    skos:definition "Inverse of has antihypertensive."@en ;
    rdfs:domain ht:Antihypertensive ; rdfs:range ht:Hypertension .
