```turtle
@prefix ht:   <http://example.org/onto/hypertension#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .

ht: a owl:Ontology ;
    rdfs:label "Hypertension Ontology"@en ;
    rdfs:comment "An ontology modeling hypertension classification, etiology, measurement, treatment, risk factors and target-organ damage as stated in the supplied corpus."@en .

#################################################################
# TOP-LEVEL KIND DISJOINTNESS
#################################################################

owl:AllDisjointClasses [
    owl:members ( ht:BloodPressureReading ht:Hypertension ht:SecondaryCause
                  ht:Antihypertensive ht:TargetOrganDamage ht:RiskFactor )
] .

#################################################################
# BLOOD PRESSURE READING + REIFIED AXIS
#################################################################

ht:BloodPressureReading a owl:Class ;
    rdfs:label "Blood Pressure Reading"@en ;
    skos:definition "A measured pair of systolic and diastolic blood pressure values, expressed in millimetres of mercury."@en ;
    rdfs:subClassOf [ a owl:Restriction ; owl:onProperty ht:hasSystolicValue ;
          owl:qualifiedCardinality 1 ; owl:onDataRange xsd:integer ] ,
        [ a owl:Restriction ; owl:onProperty ht:hasDiastolicValue ;
          owl:qualifiedCardinality 1 ; owl:onDataRange xsd:integer ] .

ht:hasSystolicValue a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has systolic value"@en ;
    skos:definition "The maximum arterial pressure, in mmHg, recorded during one heartbeat."@en ;
    rdfs:domain ht:BloodPressureReading ; rdfs:range xsd:integer .

ht:hasDiastolicValue a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has diastolic value"@en ;
    skos:definition "The minimum arterial pressure, in mmHg, recorded between heartbeats."@en ;
    rdfs:domain ht:BloodPressureReading ; rdfs:range xsd:integer .

ht:BloodPressureCategory a owl:Class ;
    rdfs:label "Blood Pressure Category"@en ;
    skos:definition "A named band of the 2017 ACC/AHA blood pressure classification scheme, realized directly from the numeric systolic/diastolic values of a reading."@en ;
    rdfs:comment "Competing guideline schemes (ESC/ESH 2018/2023 grades, JNC 7, WHO, ISH 2020, NICE NG136) use different numeric cut-points for conceptually similar bands; only the ACC/AHA 2017 scheme is modeled as classes here."@en ;
    rdfs:subClassOf ht:BloodPressureReading .

ht:hasBloodPressureCategory a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has blood pressure category"@en ;
    skos:definition "Relates a blood pressure reading to the single ACC/AHA category it falls into."@en ;
    rdfs:domain ht:BloodPressureReading ; rdfs:range ht:BloodPressureCategory .

ht:isBloodPressureCategoryOf a owl:ObjectProperty ;
    rdfs:label "is blood pressure category of"@en ;
    skos:definition "Inverse of has blood pressure category."@en ;
    owl:inverseOf ht:hasBloodPressureCategory ;
    rdfs:domain ht:BloodPressureCategory ; rdfs:range ht:BloodPressureReading .

ht:NormalBloodPressure a owl:Class ;
    rdfs:label "Normal Blood Pressure"@en ;
    skos:definition "A blood pressure reading with systolic pressure below 120 mmHg and diastolic pressure below 80 mmHg."@en ;
    rdfs:subClassOf ht:BloodPressureCategory ;
    owl:equivalentClass [ owl:intersectionOf ( ht:BloodPressureReading
        [ a owl:Restriction ; owl:onProperty ht:hasSystolicValue ; owl:someValuesFrom
            [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
              owl:withRestrictions ( [ xsd:maxExclusive 120 ] ) ] ]
        [ a owl:Restriction ; owl:onProperty ht:hasDiastolicValue ; owl:someValuesFrom
            [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
              owl:withRestrictions ( [ xsd:maxExclusive 80 ] ) ] ] ) ] .

ht:ElevatedBloodPressure a owl:Class ;
    rdfs:label "Elevated Blood Pressure"@en ;
    skos:altLabel "Prehypertension"@en ;
    skos:definition "A blood pressure reading with systolic pressure of 120 to 129 mmHg and diastolic pressure below 80 mmHg."@en ;
    rdfs:comment "Previously termed prehypertension under JNC 7 (120-139/80-89 mmHg); ESC 2024 defines an overlapping but differently-bounded 'Elevated Blood Pressure' category of 120-139/70-89 mmHg."@en ;
    rdfs:subClassOf ht:BloodPressureCategory ;
    owl:equivalentClass [ owl:intersectionOf ( ht:BloodPressureReading
        [ a owl:Restriction ; owl:onProperty ht:hasSystolicValue ; owl:someValuesFrom
            [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
              owl:withRestrictions ( [ xsd:minInclusive 120 ] [ xsd:maxInclusive 129 ] ) ] ]
        [ a owl:Restriction ; owl:onProperty ht:hasDiastolicValue ; owl:someValuesFrom
            [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
              owl:withRestrictions ( [ xsd:maxExclusive 80 ] ) ] ] ) ] .

ht:Stage1Hypertension a owl:Class ;
    rdfs:label "Stage 1 Hypertension"@en ;
    skos:definition "A blood pressure reading with systolic pressure of 130 to 139 mmHg or diastolic pressure of 80 to 89 mmHg."@en ;
    rdfs:comment "ESC/ESH classifies the same numeric range (130-139/85-89 mmHg) as 'high-normal', not as hypertension."@en ;
    rdfs:subClassOf ht:BloodPressureCategory ;
    owl:equivalentClass [ owl:intersectionOf ( ht:BloodPressureReading
        [ owl:unionOf (
            [ a owl:Restriction ; owl:onProperty ht:hasSystolicValue ; owl:someValuesFrom
                [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
                  owl:withRestrictions ( [ xsd:minInclusive 130 ] [ xsd:maxInclusive 139 ] ) ] ]
            [ a owl:Restriction ; owl:onProperty ht:hasDiastolicValue ; owl:someValuesFrom
                [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
                  owl:withRestrictions ( [ xsd:minInclusive 80 ] [ xsd:maxInclusive 89 ] ) ] ]
        ) ] ) ] .

ht:Stage2Hypertension a owl:Class ;
    rdfs:label "Stage 2 Hypertension"@en ;
    skos:definition "A blood pressure reading with systolic pressure of 140 mmHg or greater or diastolic pressure of 90 mmHg or greater."@en ;
    rdfs:subClassOf ht:BloodPressureCategory ;
    owl:equivalentClass [ owl:intersectionOf ( ht:BloodPressureReading
        [ owl:unionOf (
            [ a owl:Restriction ; owl:onProperty ht:hasSystolicValue ; owl:someValuesFrom
                [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
                  owl:withRestrictions ( [ xsd:minInclusive 140 ] ) ] ]
            [ a owl:Restriction ; owl:onProperty ht:hasDiastolicValue ; owl:someValuesFrom
                [ a rdfs:Datatype ; owl:onDatatype xsd:integer ;
                  owl:withRestrictions ( [ xsd:minInclusive 90 ] ) ] ]
        ) ] ) ] .

owl:AllDisjointClasses [
    owl:members ( ht:NormalBloodPressure ht:ElevatedBloodPressure
                  ht:Stage1Hypertension ht:Stage2Hypertension )
] .

#################################################################
# HYPERTENSION (DISEASE) AND SUBTYPES
#################################################################

ht:Hypertension a owl:Class ;
    rdfs:label "Hypertension"@en ;
    skos:altLabel "High Blood Pressure"@en ;
    skos:definition "A chronic medical condition characterized by sustained elevation of arterial blood pressure."@en ;
    rdfs:comment "The diagnostic systolic threshold is contested: the 2017 ACC/AHA guideline diagnoses hypertension at 130 mmHg systolic, while ESC/ESH, JNC 7, WHO, and ISH use 140 mmHg systolic. This single functional property honestly represents the controversy rather than scattering it across subclasses."@en .

ht:hasDiagnosticSystolicThreshold a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has diagnostic systolic threshold"@en ;
    skos:definition "The systolic blood pressure value, in mmHg, at or above which a guideline diagnoses hypertension."@en ;
    rdfs:domain ht:Hypertension ; rdfs:range xsd:integer ;
    rdfs:comment "Competing values documented in the corpus: 130 (ACC/AHA 2017) vs 140 (ESC/ESH 2018/2023, JNC 7, WHO, ISH 2020)."@en .

ht:PrimaryHypertension a owl:Class ;
    rdfs:label "Primary Hypertension"@en ;
    skos:altLabel "Essential Hypertension"@en , "Idiopathic Hypertension"@en ;
    skos:definition "Hypertension with no single identifiable underlying cause, arising from interacting genetic and environmental/lifestyle factors."@en ;
    rdfs:comment "Prevalence figures conflict across sources: approximately 85% (several sources), and 90-95% (other sources)."@en ;
    rdfs:subClassOf ht:Hypertension .

ht:SecondaryHypertension a owl:Class ;
    rdfs:label "Secondary Hypertension"@en ;
    skos:altLabel "Inessential Hypertension"@en ;
    skos:definition "Hypertension that has a specific, identifiable, and often correctable underlying cause."@en ;
    rdfs:comment "Prevalence figures conflict across sources: approximately 5-10% (several sources), approximately 10% (one in ten), and strongly age-dependent (70-85% in children under 12, 10-15% in adolescents, 17% in adults 65+)."@en ;
    rdfs:subClassOf ht:Hypertension ;
    owl:equivalentClass [ owl:intersectionOf ( ht:Hypertension
        [ a owl:Restriction ; owl:onProperty ht:hasSecondaryCause ; owl:someValuesFrom ht:SecondaryCause ] ) ] .

owl:AllDisjointClasses [ owl:members ( ht:PrimaryHypertension ht:SecondaryHypertension ) ] .

ht:IsolatedSystolicHypertension a owl:Class ;
    rdfs:label "Isolated Systolic Hypertension"@en ;
    skos:altLabel "ISH"@en ;
    skos:definition "Hypertension characterized by a disproportionate elevation of systolic pressure with a preserved or low diastolic pressure, producing a widened pulse pressure; the predominant form of hypertension in older adults."@en ;
    rdfs:comment "Traditionally defined as systolic >140 mmHg with diastolic <90 mmHg; under the 2017 ACC/AHA guideline a systolic pressure of 130 mmHg is now considered hypertensive at all ages. Most cases are due to primary hypertension, but it may occasionally result from a secondary cause such as hypothyroidism, hyperthyroidism, chronic kidney disease, or atherosclerotic renal artery stenosis."@en ;
    rdfs:subClassOf ht:Hypertension .

ht:WhiteCoatHypertension a owl:Class ;
    rdfs:label "White Coat Hypertension"@en ;
    skos:altLabel "White Coat Syndrome"@en , "WCH"@en ;
    skos:definition "A form of labile hypertension in which office blood pressure is consistently elevated while out-of-office blood pressure is normal."@en ;
    rdfs:subClassOf ht:Hypertension .

ht:MaskedHypertension a owl:Class ;
    rdfs:label "Masked Hypertension"@en ;
    skos:altLabel "MH"@en ;
    skos:definition "A blood pressure phenotype in which office blood pressure is normal while out-of-office blood pressure is consistently elevated, the inverse pattern of white coat hypertension."@en ;
    rdfs:subClassOf ht:Hypertension .

owl:AllDisjointClasses [ owl:members ( ht:WhiteCoatHypertension ht:MaskedHypertension ) ] .

ht:ResistantHypertension a owl:Class ;
    rdfs:label "Resistant Hypertension"@en ;
    skos:definition "Hypertension that remains uncontrolled to goal despite adherence to at least three suitably dosed antihypertensive medications of different classes, one of which is a diuretic, after confirming adherence and excluding the white coat effect; blood pressure requiring four or more agents is likewise regarded as resistant."@en ;
    rdfs:subClassOf ht:Hypertension ;
    owl:equivalentClass [ owl:intersectionOf ( ht:Hypertension
        [ a owl:Restriction ; owl:onProperty ht:hasAntihypertensive ;
          owl:minQualifiedCardinality 3 ; owl:onClass ht:Antihypertensive ] ) ] .

ht:HypertensiveCrisis a owl:Class ;
    rdfs:label "Hypertensive Crisis"@en ;
    skos:definition "A severe, acute elevation of blood pressure, generally a systolic pressure of 180 mmHg or higher and/or a diastolic pressure of 120 mmHg or higher, classified according to the presence or absence of acute target-organ damage."@en ;
    rdfs:subClassOf ht:Hypertension .

ht:HypertensiveUrgency a owl:Class ;
    rdfs:label "Hypertensive Urgency"@en ;
    skos:definition "A hypertensive crisis without evidence of acute target-organ damage, typically managed with gradual oral blood pressure reduction over 24 to 48 hours."@en ;
    rdfs:subClassOf ht:HypertensiveCrisis .

ht:HypertensiveEmergency a owl:Class ;
    rdfs:label "Hypertensive Emergency"@en ;
    skos:definition "A hypertensive crisis accompanied by acute hypertension-mediated target-organ damage, requiring immediate, controlled reduction of blood pressure, usually with intravenous agents in a monitored setting."@en ;
    rdfs:subClassOf ht:HypertensiveCrisis ;
    owl:equivalentClass [ owl:intersectionOf ( ht:HypertensiveCrisis
        [ a owl:Restriction ; owl:onProperty ht:hasTargetOrganDamage ; owl:someValuesFrom ht:TargetOrganDamage ] ) ] .

owl:AllDisjointClasses [ owl:members ( ht:HypertensiveUrgency ht:HypertensiveEmergency ) ] .

#################################################################
# SECONDARY CAUSES
#################################################################

ht:SecondaryCause a owl:Class ;
    rdfs:label "Secondary Cause"@en ;
    skos:definition "An identifiable underlying medical condition, drug, or substance responsible for elevated blood pressure in secondary hypertension."@en .

ht:hasSecondaryCause a owl:ObjectProperty ;
    rdfs:label "has secondary cause"@en ;
    skos:definition "Relates secondary hypertension to its identifiable underlying cause."@en ;
    rdfs:domain ht:SecondaryHypertension ; rdfs:range ht:SecondaryCause .

ht:isSecondaryCauseOf a owl:ObjectProperty ;
    rdfs:label "is secondary cause of"@en ;
    skos:definition "Inverse of has secondary cause."@en ;
    owl:inverseOf ht:hasSecondaryCause ;
    rdfs:domain ht:SecondaryCause ; rdfs:range ht:SecondaryHypertension .

ht:RenalCause a owl:Class ;
    rdfs:label "Renal Cause"@en ;
    skos:definition "A secondary cause of hypertension arising from kidney disease, the most common category of secondary hypertension."@en ;
    rdfs:subClassOf ht:SecondaryCause .

ht:RenalParenchymalDisease a owl:Class ;
    rdfs:label "Renal Parenchymal Disease"@en ;
    skos:definition "Disease of the kidney tissue itself, including diabetic nephropathy, glomerulonephritis, interstitial disorders, and polycystic kidney disease, that causes secondary hypertension."@en ;
    rdfs:subClassOf ht:RenalCause .

ht:RenovascularDisease a owl:Class ;
    rdfs:label "Renovascular Disease"@en ;
    skos:definition "Secondary hypertension produced by obstruction or narrowing of the renal artery."@en ;
    rdfs:subClassOf ht:RenalCause .

ht:RenalArteryStenosis a owl:Class ;
    rdfs:label "Renal Artery Stenosis"@en ;
    skos:definition "Narrowing of the renal artery that produces renovascular hypertension."@en ;
    rdfs:subClassOf ht:RenovascularDisease .

owl:AllDisjointClasses [ owl:members ( ht:RenalParenchymalDisease ht:RenovascularDisease ) ] .

ht:EndocrineCause a owl:Class ;
    rdfs:label "Endocrine Cause"@en ;
    skos:definition "A secondary cause of hypertension arising from a hormonal disturbance."@en ;
    rdfs:subClassOf ht:SecondaryCause .

ht:PrimaryAldosteronism a owl:Class ;
    rdfs:label "Primary Aldosteronism"@en ;
    skos:altLabel "Conn's Syndrome"@en ;
    skos:definition "Autonomous overproduction of aldosterone by the adrenal glands, most often due to an aldosterone-producing adenoma or bilateral adrenal hyperplasia, accounting for most endocrine-related secondary hypertension and up to one in five cases of resistant hypertension."@en ;
    rdfs:subClassOf ht:EndocrineCause .

ht:Pheochromocytoma a owl:Class ;
    rdfs:label "Pheochromocytoma"@en ;
    skos:definition "A tumor resulting in excessive secretion of norepinephrine and epinephrine, promoting vasoconstriction and raising blood pressure."@en ;
    rdfs:subClassOf ht:EndocrineCause .

ht:CushingSyndrome a owl:Class ;
    rdfs:label "Cushing Syndrome"@en ;
    skos:definition "Secondary hypertension resulting from excess glucocorticoids."@en ;
    rdfs:subClassOf ht:EndocrineCause .

ht:ThyroidDisease a owl:Class ;
    rdfs:label "Thyroid Disease"@en ;
    skos:definition "Hyperthyroidism or hypothyroidism recognized as a contributor to secondary hypertension."@en ;
    rdfs:subClassOf ht:EndocrineCause .

ht:PrimaryHyperparathyroidism a owl:Class ;
    rdfs:label "Primary Hyperparathyroidism"@en ;
    skos:definition "Excess parathyroid hormone secretion recognized as a contributor to secondary hypertension."@en ;
    rdfs:subClassOf ht:EndocrineCause .

owl:AllDisjointClasses [
    owl:members ( ht:PrimaryAldosteronism ht:Pheochromocytoma ht:CushingSyndrome
                  ht:ThyroidDisease ht:PrimaryHyperparathyroidism )
] .

ht:VascularCause a owl:Class ;
    rdfs:label "Vascular Cause"@en ;
    skos:definition "A secondary cause of hypertension arising from a structural abnormality of the large blood vessels."@en ;
    rdfs:subClassOf ht:SecondaryCause .

ht:AorticCoarctation a owl:Class ;
    rdfs:label "Aortic Coarctation"@en ;
    skos:altLabel "Coarctation of the Aorta"@en ;
    skos:definition "A congenital narrowing of the aorta that typically produces secondary hypertension in younger patients."@en ;
    rdfs:subClassOf ht:VascularCause .

ht:ObstructiveSleepApnea a owl:Class ;
    rdfs:label "Obstructive Sleep Apnea"@en ;
    skos:altLabel "OSA"@en ;
    skos:definition "A sleep-related breathing disorder that is one of the most common causes of secondary hypertension and is also common among patients with resistant hypertension."@en ;
    rdfs:subClassOf ht:SecondaryCause .

ht:DrugInducedCause a owl:Class ;
    rdfs:label "Drug Induced Cause"@en ;
    skos:definition "Elevated blood pressure caused by a medication or substance, including NSAIDs, sympathomimetic decongestants, stimulants, corticosteroids, oral contraceptives, licorice, cyclosporine, cocaine, and methamphetamine."@en ;
    rdfs:subClassOf ht:SecondaryCause .

owl:AllDisjointClasses [
    owl:members ( ht:RenalCause ht:EndocrineCause ht:VascularCause
                  ht:ObstructiveSleepApnea ht:DrugInducedCause )
] .

#################################################################
# RISK FACTORS
#################################################################

ht:RiskFactor a owl:Class ;
    rdfs:label "Risk Factor"@en ;
    skos:definition "A factor that increases the likelihood of developing hypertension."@en .

ht:hasRiskFactor a owl:ObjectProperty ;
    rdfs:label "has risk factor"@en ;
    skos:definition "Relates hypertension to a factor that increases its likelihood or severity."@en ;
    rdfs:domain ht:Hypertension ; rdfs:range ht:RiskFactor .

ht:isRiskFactorOf a owl:ObjectProperty ;
    rdfs:label "is risk factor of"@en ;
    skos:definition "Inverse of has risk factor."@en ;
    owl:inverseOf ht:hasRiskFactor ;
    rdfs:domain ht:RiskFactor ; rdfs:range ht:Hypertension .

ht:ModifiableRiskFactor a owl:Class ;
    rdfs:label "Modifiable Risk Factor"@en ;
    skos:definition "A risk factor for hypertension that can be changed through behavior or treatment."@en ;
    rdfs:subClassOf ht:RiskFactor .

ht:NonModifiableRiskFactor a owl:Class ;
    rdfs:label "Non Modifiable Risk Factor"@en ;
    skos:definition "A risk factor for hypertension that cannot be changed."@en ;
    rdfs:subClassOf ht:RiskFactor .

owl:AllDisjointClasses [ owl:members ( ht:ModifiableRiskFactor ht:NonModifiableRiskFactor ) ] .

ht:ExcessSaltIntake a owl:Class ;
    rdfs:label "Excess Salt Intake"@en ;
    skos:definition "Elevated dietary sodium consumption; approximately 50 to 60% of hypertensive patients demonstrate salt-responsive physiology."@en ;
    rdfs:subClassOf ht:ModifiableRiskFactor .

ht:Obesity a owl:Class ;
    rdfs:label "Obesity"@en ;
    skos:definition "Excess body weight, a modifiable risk factor for hypertension; weight reduction alone can decrease systolic pressure by 5 to 20 mmHg."@en ;
    rdfs:subClassOf ht:ModifiableRiskFactor .

ht:PhysicalInactivity a owl:Class ;
    rdfs:label "Physical Inactivity"@en ;
    skos:definition "Lack of regular exercise, a modifiable risk factor for hypertension."@en ;
    rdfs:subClassOf ht:ModifiableRiskFactor .

ht:TobaccoUse a owl:Class ;
    rdfs:label "Tobacco Use"@en ;
    skos:definition "Smoking or other tobacco consumption, a modifiable risk factor for hypertension."@en ;
    rdfs:subClassOf ht:ModifiableRiskFactor .

ht:AlcoholUse a owl:Class ;
    rdfs:label "Alcohol Use"@en ;
    skos:definition "Consumption of alcohol, a modifiable risk factor positively associated with higher blood pressure."@en ;
    rdfs:subClassOf ht:ModifiableRiskFactor .

owl:AllDisjointClasses [
    owl:members ( ht:ExcessSaltIntake ht:Obesity ht:PhysicalInactivity ht:TobaccoUse ht:AlcoholUse )
] .

ht:AdvancingAge a owl:Class ;
    rdfs:label "Advancing Age"@en ;
    skos:definition "Increasing age, a non-modifiable risk factor; prevalence of hypertension rises to as much as 60% of the population above 60 years."@en ;
    rdfs:subClassOf ht:NonModifiableRiskFactor .

ht:FamilyHistory a owl:Class ;
    rdfs:label "Family History"@en ;
    skos:definition "A family history of hypertension, a non-modifiable risk factor reflecting heritability of the condition."@en ;
    rdfs:subClassOf ht:NonModifiableRiskFactor .

ht:Genetics a owl:Class ;
    rdfs:label "Genetics"@en ;
    skos:definition "Genetic predisposition, including more than 2,000 common genetic variants with small effects on blood pressure, a non-modifiable risk factor for hypertension."@en ;
    rdfs:subClassOf ht:NonModifiableRiskFactor .

ht:Race a owl:Class ;
    rdfs:label "Race"@en ;
    skos:definition "Race, a non-modifiable risk factor that also influences first-line treatment selection."@en ;
    rdfs:subClassOf ht:NonModifiableRiskFactor .

ht:Sex a owl:Class ;
    rdfs:label "Sex"@en ;
    skos:definition "Biological sex, a non-modifiable risk factor for hypertension."@en ;
    rdfs:subClassOf ht:NonModifiableRiskFactor .

owl:AllDisjointClasses [
    owl:members ( ht:AdvancingAge ht:FamilyHistory ht:Genetics ht:Race ht:Sex )
] .

#################################################################
# TARGET ORGAN DAMAGE
#################################################################

ht:TargetOrganDamage a owl:Class ;
    rdfs:label "Target Organ Damage"@en ;
    skos:altLabel "Hypertension Mediated Organ Damage"@en ;
    skos:definition "Structural or functional injury to an organ resulting from sustained or severe elevation of blood pressure."@en .

ht:hasTargetOrganDamage a owl:ObjectProperty ;
    rdfs:label "has target organ damage"@en ;
    skos:definition "Relates hypertension to organ injury it has caused."@en ;
    rdfs:domain ht:Hypertension ; rdfs:range ht:TargetOrganDamage .

ht:isTargetOrganDamageOf a owl:ObjectProperty ;
    rdfs:label "is target organ damage of"@en ;
    skos:definition "Inverse of has target organ damage."@en ;
    owl:inverseOf ht:hasTargetOrganDamage ;
    rdfs:domain ht:TargetOrganDamage ; rdfs:range ht:Hypertension .

ht:HypertensiveHeartDisease a owl:Class ;
    rdfs:label "Hypertensive Heart Disease"@en ;
    skos:definition "A constellation of structural and functional changes in the left ventricle, left atrium, and coronary arteries resulting from chronic blood pressure elevation."@en ;
    rdfs:subClassOf ht:TargetOrganDamage .

ht:LeftVentricularHypertrophy a owl:Class ;
    rdfs:label "Left Ventricular Hypertrophy"@en ;
    skos:altLabel "LVH"@en ;
    skos:definition "Thickening of the left ventricular wall in compensatory response to chronic pressure overload; the hallmark structural manifestation of hypertensive heart disease."@en ;
    rdfs:subClassOf ht:HypertensiveHeartDisease .

ht:HypertensiveRetinopathy a owl:Class ;
    rdfs:label "Hypertensive Retinopathy"@en ;
    skos:definition "Damage to the retina and retinal circulation caused by sustained or abrupt elevation of blood pressure, observable directly by ophthalmoscopy."@en ;
    rdfs:subClassOf ht:TargetOrganDamage .

ht:HypertensiveNephropathy a owl:Class ;
    rdfs:label "Hypertensive Nephropathy"@en ;
    skos:altLabel "Hypertensive Kidney Disease"@en , "Nephrosclerosis"@en ;
    skos:definition "Kidney failure or progressive kidney damage attributable to chronic hypertension, characterized by hardening and thickening of small renal vessels, glomeruli, tubules, and interstitial tissue (nephrosclerosis), reducing blood and oxygen supply to renal tissue."@en ;
    rdfs:subClassOf ht:TargetOrganDamage .

ht:HypertensiveEncephalopathy a owl:Class ;
    rdfs:label "Hypertensive Encephalopathy"@en ;
    skos:definition "Brain swelling and dysfunction caused by severely elevated blood pressure, presenting with headache, confusion, or visual disturbance, and a defining manifestation of hypertensive emergency."@en ;
    rdfs:subClassOf ht:TargetOrganDamage .

owl:AllDisjointClasses [
    owl:members ( ht:HypertensiveHeartDisease ht:HypertensiveRetinopathy
                  ht:HypertensiveNephropathy ht:HypertensiveEncephalopathy )
] .

ht:RetinalFinding a owl:Class ;
    rdfs:label "Retinal Finding"@en ;
    skos:definition "A specific abnormality of the retina or retinal vessels observed on ophthalmoscopic examination in hypertensive retinopathy."@en .

ht:hasRetinalFinding a owl:ObjectProperty ;
    rdfs:label "has retinal finding"@en ;
    skos:definition "Relates hypertensive retinopathy to a specific retinal abnormality it exhibits."@en ;
    rdfs:domain ht:HypertensiveRetinopathy ; rdfs:range ht:RetinalFinding .

ht:isRetinalFindingOf a owl:ObjectProperty ;
    rdfs:label "is retinal finding of"@en ;
    skos:definition "Inverse of has retinal finding."@en ;
    owl:inverseOf ht:hasRetinalFinding ;
    rdfs:domain ht:RetinalFinding ; rdfs:range ht:HypertensiveRetinopathy .

ht:ArteriolarNarrowing a owl:Class ;
    rdfs:label "Arteriolar Narrowing"@en ;
    skos:definition "Generalized or focal narrowing of the retinal arterioles, an early finding of hypertensive retinopathy."@en ;
    rdfs:subClassOf ht:RetinalFinding .

ht:ArteriovenousNicking a owl:Class ;
    rdfs:label "Arteriovenous Nicking"@en ;
    skos:altLabel "AV Nicking"@en , "AV Nipping"@en ;
    skos:definition "Compression of a retinal vein where it is crossed by a sclerotic arteriole, a finding of hypertensive retinopathy."@en ;
    rdfs:subClassOf ht:RetinalFinding .

ht:RetinalHemorrhage a owl:Class ;
    rdfs:label "Retinal Hemorrhage"@en ;
    skos:altLabel "Flame Hemorrhage"@en , "Blot Hemorrhage"@en ;
    skos:definition "Bleeding into the retinal tissue resulting from breakdown of the blood-retinal barrier in advanced hypertensive retinopathy."@en ;
    rdfs:subClassOf ht:RetinalFinding .

ht:CottonWoolSpot a owl:Class ;
    rdfs:label "Cotton Wool Spot"@en ;
    skos:definition "A retinal ischemic lesion appearing as a white, fluffy patch, seen in advanced hypertensive retinopathy."@en ;
    rdfs:subClassOf ht:RetinalFinding .

ht:HardExudate a owl:Class ;
    rdfs:label "Hard Exudate"@en ;
    skos:definition "Lipid deposits in the retina resulting from leakage through damaged retinal vessels in hypertensive retinopathy."@en ;
    rdfs:subClassOf ht:RetinalFinding .

ht:Papilledema a owl:Class ;
    rdfs:label "Papilledema"@en ;
    skos:altLabel "Optic Disc Edema"@en ;
    skos:definition "Swelling of the optic disc, the most severe retinal finding, indicating malignant hypertensive retinopathy."@en ;
    rdfs:subClassOf ht:RetinalFinding .

owl:AllDisjointClasses [
    owl:members ( ht:ArteriolarNarrowing ht:ArteriovenousNicking ht:RetinalHemorrhage
                  ht:CottonWoolSpot ht:HardExudate ht:Papilledema )
] .

#################################################################
# ANTIHYPERTENSIVE DRUG CLASSES
#################################################################

ht:Antihypertensive a owl:Class ;
    rdfs:label "Antihypertensive"@en ;
    skos:definition "A class of medication used to lower elevated blood pressure."@en .

ht:hasAntihypertensive a owl:ObjectProperty ;
    rdfs:label "has antihypertensive"@en ;
    skos:definition "Relates hypertension to a class of medication used in its treatment."@en ;
    rdfs:domain ht:Hypertension ; rdfs:range ht:Antihypertensive .

ht:isAntihypertensiveOf a owl:ObjectProperty ;
    rdfs:label "is antihypertensive of"@en ;
    skos:definition "Inverse of has antihypertensive."@en ;
    owl:inverseOf ht:hasAntihypertensive ;
    rdfs:domain ht:Antihypertensive ; rdfs:range ht:Hypertension .

ht:ThiazideDiuretic a owl:Class ;
    rdfs:label "Thiazide Diuretic"@en ;
    skos:altLabel "Thiazide-type Diuretic"@en ;
    skos:definition "A first-line antihypertensive drug class that blocks sodium reabsorption at the sodium-chloride cotransporter in the distal convoluted tubule, promoting natriuresis and diuresis and reducing intravascular volume."@en ;
    rdfs:subClassOf ht:Antihypertensive .

ht:CalciumChannelBlocker a owl:Class ;
    rdfs:label "Calcium Channel Blocker"@en ;
    skos:altLabel "CCB"@en ;
    skos:definition "A first-line antihypertensive drug class that inhibits calcium entry through L-type voltage-gated calcium channels in cardiac and vascular smooth muscle."@en ;
    rdfs:subClassOf ht:Antihypertensive .

ht:Dihydropyridine a owl:Class ;
    rdfs:label "Dihydropyridine"@en ;
    skos:definition "A subtype of calcium channel blocker that causes peripheral vasodilation and is preferred for the treatment of hypertension."@en ;
    rdfs:subClassOf ht:CalciumChannelBlocker .

ht:NonDihydropyridine a owl:Class ;
    rdfs:label "Non Dihydropyridine"@en ;
    skos:definition "A subtype of calcium channel blocker, such as verapamil and diltiazem, that primarily affects cardiac contractility and atrioventricular conduction, making it better suited to arrhythmia management."@en ;
    rdfs:subClassOf ht:CalciumChannelBlocker .

owl:AllDisjointClasses [ owl:members ( ht:Dihydropyridine ht:NonDihydropyridine ) ] .

ht:AngiotensinConvertingEnzymeInhibitor a owl:Class ;
    rdfs:label "Angiotensin Converting Enzyme Inhibitor"@en ;
    skos:altLabel "ACE Inhibitor"@en , "ACEI"@en ;
    skos:definition "A first-line antihypertensive drug class that inhibits the angiotensin-converting enzyme, decreasing production of angiotensin II and increasing bradykinin, thereby promoting vasodilation."@en ;
    rdfs:subClassOf ht:Antihypertensive .

ht:AngiotensinReceptorBlocker a owl:Class ;
    rdfs:label "Angiotensin Receptor Blocker"@en ;
    skos:altLabel "ARB"@en , "Angiotensin II Receptor Blocker"@en ;
    skos:definition "A first-line antihypertensive drug class that blocks the binding of angiotensin II to the angiotensin type 1 receptor, rather than affecting its production."@en ;
    rdfs:subClassOf ht:Antihypertensive .

ht:BetaBlocker a owl:Class ;
    rdfs:label "Beta Blocker"@en ;
    skos:definition "An antihypertensive drug class that inhibits catecholamines from binding to beta-adrenergic receptors, decreasing heart rate and myocardial oxygen consumption; no longer recommended as first-line treatment for uncomplicated hypertension except with a compelling cardiac indication."@en ;
    rdfs:subClassOf ht:Antihypertensive .

owl:AllDisjointClasses [
    owl:members ( ht:ThiazideDiuretic ht:CalciumChannelBlocker
                  ht:AngiotensinConvertingEnzymeInhibitor ht:AngiotensinReceptorBlocker ht:BetaBlocker )
] .

#################################################################
# MEASUREMENT METHODS AND SETTINGS
#################################################################

ht:BloodPressureMeasurementMethod a owl:Class ;
    rdfs:label "Blood Pressure Measurement Method"@en ;
    skos:definition "A technique used to measure arterial blood pressure."@en .

ht:AuscultatoryMethod a owl:Class ;
    rdfs:label "Auscultatory Method"@en ;
    skos:definition "A blood pressure measurement method using a stethoscope and sphygmomanometer, in which systolic and diastolic pressures are identified from the onset and disappearance of Korotkoff sounds."@en ;
    rdfs:subClassOf ht:BloodPressureMeasurementMethod .

ht:OscillometricMethod a owl:Class ;
    rdfs:label "Oscillometric Method"@en ;
    skos:definition "An automated blood pressure measurement method that calculates systolic, diastolic, and mean arterial pressures from oscillations in cuff pressure, requiring less operator skill than the auscultatory method."@en ;
    rdfs:subClassOf ht:BloodPressureMeasurementMethod .

owl:AllDisjointClasses [ owl:members ( ht:AuscultatoryMethod ht:OscillometricMethod ) ] .

ht:BloodPressureMeasurementSetting a owl:Class ;
    rdfs:label "Blood Pressure Measurement Setting"@en ;
    skos:definition "The clinical or non-clinical context in which a blood pressure reading is obtained."@en .

ht:OfficeBloodPressureMeasurement a owl:Class ;
    rdfs:label "Office Blood Pressure Measurement"@en ;
    skos:definition "Blood pressure measurement taken in a clinical setting such as a doctor's office or hospital."@en ;
    rdfs:subClassOf ht:BloodPressureMeasurementSetting .

ht:AmbulatoryBloodPressureMonitoring a owl:Class ;
    rdfs:label "Ambulatory Blood Pressure Monitoring"@en ;
    skos:altLabel "ABPM"@en ;
    skos:definition "Blood pressure measurement taken at regular intervals over a full 24-hour sleep-wake cycle outside the clinical setting; the reference standard for distinguishing white coat and masked hypertension."@en ;
    rdfs:subClassOf ht:BloodPressureMeasurementSetting .

ht:HomeBloodPressureMonitoring a owl:Class ;
    rdfs:label "Home Blood Pressure Monitoring"@en ;
    skos:altLabel "HBPM"@en ;
    skos:definition "Blood pressure measurement taken by the patient outside the clinical setting using a home monitoring device, found to be as accurate as 24-hour ambulatory monitoring."@en ;
    rdfs:subClassOf ht:BloodPressureMeasurementSetting .

owl:AllDisjointClasses [
    owl:members ( ht:OfficeBloodPressureMeasurement ht:AmbulatoryBloodPressureMonitoring
                  ht:HomeBloodPressureMonitoring )
] .
